void _WM_GLOBAL_ERROR(const char *func, int lne, int wmerno, const char *wmfor, int error) { /* <=== _WM_GLOBAL_ERROR */ 

    char *errorstring;

    if (wmerno < 0 || wmerno >= WM_ERR_MAX)
         wmerno = WM_ERR_MAX; /* set to invalid error code. */

    _WM_Global_ErrorI = wmerno;

    if (_WM_Global_ErrorS != NULL) free(_WM_Global_ErrorS);

    errorstring = malloc(MAX_ERROR_LEN+1);

    if (error == 0) {
        if (wmfor == NULL) {
            sprintf(errorstring,"Error (%s:%i) %s",
                    func, lne, errors[wmerno]);
        } else {
            sprintf(errorstring,"Error (%s:%i) %s (%s)",
                    func, lne, wmfor, errors[wmerno]);
        }
    } else {
        if (wmfor == NULL) {
            sprintf(errorstring,"System Error (%s:%i) %s : %s",
                    func, lne, errors[wmerno], strerror(error));
        } else {
            sprintf(errorstring,"System Error (%s:%i) %s (%s) : %s",
                    func, lne, wmfor, errors[wmerno], strerror(error));
        }
    }

    errorstring[MAX_ERROR_LEN] = 0;
    _WM_Global_ErrorS = errorstring;
}

void _WM_load_patch(struct _mdi *mdi, uint16_t patchid) { /* <=== _WM_load_patch */ 
    uint32_t i;
    struct _patch *tmp_patch = NULL;

    for (i = 0; i < mdi->patch_count; i++) {
        if (mdi->patches[i]->patchid == patchid) {
            return;
        }
    }

    tmp_patch = _WM_get_patch_data(mdi, patchid);
    if (tmp_patch == NULL) {
        return;
    }

    _WM_Lock(&_WM_patch_lock);
    if (!tmp_patch->loaded) {
        if (_WM_load_sample(tmp_patch) == -1) {
            _WM_Unlock(&_WM_patch_lock);
            return;
        }
    }

    if (tmp_patch->first_sample == NULL) {
        _WM_Unlock(&_WM_patch_lock);
        return;
    }

    mdi->patch_count++;
    mdi->patches = realloc(mdi->patches,
                           (sizeof(struct _patch*) * mdi->patch_count));
    mdi->patches[mdi->patch_count - 1] = tmp_patch;
    tmp_patch->inuse_count++;
    _WM_Unlock(&_WM_patch_lock);
}

