void _WM_reset_reverb(struct _rvb *rvb) { /* <=== _WM_reset_reverb */ 
    int i, j, k;
    for (i = 0; i < rvb->l_buf_size; i++) {
        rvb->l_buf[i] = 0;
    }
    for (i = 0; i < rvb->r_buf_size; i++) {
        rvb->r_buf[i] = 0;
    }
    for (k = 0; k < 8; k++) {
        for (i = 0; i < 6; i++) {
            for (j = 0; j < 2; j++) {
                rvb->l_buf_flt_in[k][i][j] = 0;
                rvb->l_buf_flt_out[k][i][j] = 0;
                rvb->r_buf_flt_in[k][i][j] = 0;
                rvb->r_buf_flt_out[k][i][j] = 0;
            }
        }
    }
}

static int midi_setup_patch(struct _mdi *mdi, uint8_t channel, uint8_t patch) { /* <=== midi_setup_patch */ 
    MIDI_EVENT_DEBUG(__FUNCTION__,channel, patch);
    _WM_CheckEventMemoryPool(mdi);
    mdi->events[mdi->event_count].do_event = *_WM_do_patch;
    mdi->events[mdi->event_count].event_data.channel = channel;
    mdi->events[mdi->event_count].event_data.data.value = patch;
    mdi->events[mdi->event_count].samples_to_next = 0;
    mdi->event_count++;

    if (mdi->channel[channel].isdrum) {
        mdi->channel[channel].bank = patch;
    } else {
        _WM_load_patch(mdi, ((mdi->channel[channel].bank << 8) | patch));
        mdi->channel[channel].patch = _WM_get_patch_data(mdi,
                                                     ((mdi->channel[channel].bank << 8) | patch));
    }
    return (0);
}

